package protocol

import (
	"fmt"
	"net/netip"
)

// AssistKind is the kind of an assist.
type AssistKind string

// Assist kinds; any other kind is ignored and counted by the receiver.
const (
	// AssistPeerSeen (C→S→C): the reporter received a valid UDP packet from
	// its peer. The server rewrites from and strips local before forwarding.
	AssistPeerSeen AssistKind = "peer_seen"
	// AssistPeerTargets (S→C only): new targets generated by the server.
	AssistPeerTargets AssistKind = "peer_targets"
	// AssistRefresh (S→C only): before the go of Round, the server asks the
	// client for an anchor refresh in Family: two
	// new sockets, about 100 ms apart, each send one probe to the family's
	// first global observer, so natprobe sees where the sequential
	// allocator is now and how fast others move it. Accepted before the
	// summary too.
	AssistRefresh AssistKind = "refresh"
)

// TargetSource is Assist.Source: why the server pushes peer_targets.
type TargetSource string

// Target sources.
const (
	TargetsSandwich TargetSource = "sandwich"
	TargetsInject   TargetSource = "inject"
	TargetsDrift    TargetSource = "drift"
	TargetsPortmap  TargetSource = "portmap"
)

// Assist relays punch-time evidence.
//
// From, Targets, Window and Source are written by the server only. They are
// checked where they are consumed — by the client, with ValidateRelayed — and
// a server drops whatever a client put there (StripServerFields) instead of
// failing the session: such fields are dropped and counted.
type Assist struct {
	SessionID string     `json:"session_id"`
	Role      Role       `json:"role,omitempty"` // C→S: the sender (consistency check); S→C: omitted
	From      Role       `json:"from,omitempty"` // S→C: the original sender, written by the server
	Kind      AssistKind `json:"kind"`
	Round     uint8      `json:"round"`
	Family    Family     `json:"family"`
	// peer_seen
	Remote netip.AddrPort `json:"remote,omitzero"` // source of the received packet = the peer's mapping on this path
	Local  netip.AddrPort `json:"local,omitzero"`  // C→S only: the receiving socket; removed before forwarding
	Sock   uint8          `json:"sock"`            // from the packet header: the peer's sending socket
	Cand   uint16         `json:"cand"`            // from the packet header: the peer's target id (stage<<12 | idx)
	Type   uint8          `json:"type"`            // the packet's UDP type
	First  bool           `json:"first,omitempty"` // first valid packet from the peer in the session
	// peer_targets (S→C only)
	Targets []netip.AddrPort `json:"targets,omitempty"` // <= 16, all admitted by the server
	Window  *PortWindow      `json:"window,omitempty"`  // hi - lo <= 63; ip must be a verified peer IP
	Source  TargetSource     `json:"source,omitempty"`
	// common
	Meta map[string]string `json:"meta,omitempty"` // <= 8 keys, values <= 64 B, <= 1 KiB in all; caller pass-through
}

// Validate implements Message. It checks what both directions carry; the
// server-written fields are left to ValidateRelayed. Assists of an unknown
// kind only get the common checks: the receiver ignores and counts them.
func (m Assist) Validate() error {
	if err := checkSessionID(m.SessionID); err != nil {
		return err
	}
	if m.Role != "" && !m.Role.IsPunch() {
		return violation("role", "%q is not initiator or responder", m.Role)
	}
	if !isName(string(m.Kind), maxName) {
		return violation("kind", "%q is not a kind name", m.Kind)
	}
	if err := checkMeta("meta", m.Meta, maxAssistMeta); err != nil {
		return err
	}
	if m.Kind != AssistPeerSeen && m.Kind != AssistPeerTargets && m.Kind != AssistRefresh {
		return nil
	}
	if err := checkRound("round", m.Round); err != nil {
		return err
	}
	if !m.Family.Valid() {
		return violation("family", "invalid family %q", m.Family)
	}
	if m.Kind == AssistPeerSeen {
		if err := checkEndpoint("remote", m.Remote, m.Family); err != nil {
			return err
		}
		if m.Local.IsValid() {
			return checkEndpoint("local", m.Local, m.Family)
		}
	}
	return nil
}

// ValidateRelayed checks the fields the server writes, on an assist received
// from the server (after Validate): from, and for peer_targets the targets,
// the window and the source.
func (m Assist) ValidateRelayed() error {
	switch m.Kind {
	case AssistPeerSeen:
		if !m.From.IsPunch() {
			return violation("from", "%q is not initiator or responder", m.From)
		}
	case AssistRefresh:
		if m.From != RoleServer {
			return violation("from", "%q, a refresh comes from the server", m.From)
		}
	case AssistPeerTargets:
		if m.From != RoleServer {
			return violation("from", "%q, peer_targets come from the server", m.From)
		}
		for i, t := range m.Targets {
			if err := checkEndpoint(fmt.Sprintf("targets[%d]", i), t, m.Family); err != nil {
				return err
			}
		}
		if w := m.Window; w != nil {
			if !m.Family.Matches(w.IP) {
				return violation("window.ip", "%v is not a %s address", w.IP, m.Family)
			}
			if w.Lo == 0 || w.Hi < w.Lo {
				return violation("window", "bad port range [%d, %d]", w.Lo, w.Hi)
			}
		}
		if len(m.Targets) == 0 && m.Window == nil {
			return violation("targets", "neither targets nor window")
		}
		switch m.Source {
		case TargetsSandwich, TargetsInject, TargetsDrift, TargetsPortmap:
		default:
			return violation("source", "unknown source %q", m.Source)
		}
	default:
		// Every assist the server sends names its origin, whatever the kind.
		if !m.From.Valid() {
			return violation("from", "unknown role %q", m.From)
		}
	}
	return nil
}

// StripServerFields returns an assist received from a client without what
// only the server may write — from, targets, window and source — and
// whether there was anything to remove (the server counts that as
// assist_rejected).
func (m Assist) StripServerFields() (Assist, bool) {
	had := m.From != "" || len(m.Targets) > 0 || m.Window != nil || m.Source != ""
	m.From, m.Targets, m.Window, m.Source = "", nil, nil, ""
	return m, had
}

// Relayed is the assist the server forwards for a client's peer_seen: the
// sender's role moves to from, and local and the server-only fields are
// removed. The server never forwards the client's
// frame itself.
func (m Assist) Relayed(from Role) Assist {
	m, _ = m.StripServerFields()
	m.From, m.Role, m.Local = from, "", netip.AddrPort{}
	return m
}

// validateOutbound is what Marshal checks: an assist written by a server
// (from set) must pass ValidateRelayed, and one written by a client (role
// set) must not carry server-only fields.
func (m Assist) validateOutbound() error {
	if err := m.Validate(); err != nil {
		return err
	}
	switch {
	case m.From != "":
		return m.ValidateRelayed()
	case m.Role == "":
		return violation("role", "neither role (client) nor from (server)")
	case len(m.Targets) > 0 || m.Window != nil || m.Source != "":
		return violation("source", "a client assist carries server-only fields")
	}
	return nil
}
